    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    target = int(data[1 + n])
    a, b = two_sum_brute(nums, target)
    print(a, b)

import sys

def two_sum_hash(nums, target):
    seen = {}
    for i, v in enumerate(nums):
        need = target - v
        if need in seen:
            return [seen[need] + 1, i + 1]
        seen[v] = i
    return [-1, -1]

if __name__ == '__main__':
    data = sys.stdin.read().split()
